import React, { useState, useEffect } from "react";
import { Button, OverlayTrigger, Tooltip } from "react-bootstrap";
import { PencilSquare, Trash, Save, Eye } from "react-bootstrap-icons";
import "./App.css";

function Camera() {
  const [image, setImage] = useState(null);
  const [tablesData, setTablesData] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);
  const [jsonOutput, setJsonOutput] = useState(null);
  const [toast, setToast] = useState({ show: false, message: "", type: "" });
  const [progress, setProgress] = useState(0);
  const [amounts, setAmounts] = useState([]);
  const [editingRow, setEditingRow] = useState(null);
  const [editValues, setEditValues] = useState([]);
  const [currentDate, setCurrentDate] = useState(new Date().toISOString().split("T")[0]);
  const [stockDetails, setStockDetails] = useState({});
  const [stockResultsState, setStockResultsState] = useState([]);
  const [cNo, setCNo] = useState(null);
  const [shopName, setShopName] = useState("");
  const [type, setType] = useState("Godown");
  const [typeParam, setTypeParam] = useState("");
  const [numberCounter, setNumberCounter] = useState("");
  const [visibleTooltip, setVisibleTooltip] = useState("");
  const [isOpenCvReady, setIsOpenCvReady] = useState(false);
    const version = "1.0.3";

  useEffect(() => {
    const checkOpenCv = () => {
      if (window.cv && window.cv.getBuildInformation) {
        setIsOpenCvReady(true);
      } else {
        setTimeout(checkOpenCv, 100);
      }
    };
    checkOpenCv();
  }, []);

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const cNoParam = params.get("c_no");
    const typeParamValue = params.get("type");
    const numberCounterValue = params.get("number_counter");
    setTypeParam(typeParamValue);
    setNumberCounter(numberCounterValue);
    setType("Godown");
    if (cNoParam) {
      setCNo(cNoParam);
    } else {
      setError("No c_no provided in URL");
      showToast("No c_no provided in URL", "error");
    }
  }, []);

  useEffect(() => {
    console.log("Type parameter changed:", typeParam);
  }, [typeParam]);

  const showToast = (message, type = "info") => {
    setToast({ show: true, message, type });
    setTimeout(() => setToast({ show: false, message: "", type: "" }), 3000);
  };

  const closeToast = () => {
    setToast({ show: false, message: "", type: "" });
  };

  useEffect(() => {
    const fetchShopDetails = async () => {
      if (!cNo) return;
      try {
        const url = `https://deepikagroups.in/admin/api/getShopsList.php?type=${typeParam}&c_no=${cNo}`;
        const response = await fetch(url);
        if (!response.ok) throw new Error("Failed to fetch shop details");
        const data = await response.json();
        const shopDetails = data.shop_details || [];
        const shop = shopDetails.find((shop) => String(shop.id) === String(cNo));
        if (shop) {
          setShopName(decodeURIComponent(shop.name || "Unnamed Shop"));
        } else {
          showToast(`No shop found for c_no: ${cNo}`, "error");
          setShopName("Unnamed Shop");
        }
      } catch (err) {
        console.error("Error fetching shop details:", err);
        showToast(`Failed to fetch shop details: ${err.message}`, "error");
        setShopName("Unnamed Shop");
      }
    };
    fetchShopDetails();
  }, [cNo, typeParam]);

  const cleanProductName = (name) =>
    typeof name === "string" ? name.replace(/\s*\(\d+\)\s*$/, "").trim() : name;

  const fetchProductStockDetails = async (productName, tableIndex, rowIndex) => {
    if (!cNo || !currentDate) {
      return { tableIndex, rowIndex, error: "Missing c_no or date" };
    }
    try {
      const newProductName = cleanProductName(productName);
      const encodedProductName = encodeURIComponent(newProductName);
      const url = `https://deepikagroups.in/admin/api/getProductStockDetails.php?type=${type}&c_no=${cNo}&date=${currentDate}&product_name=${encodedProductName}`;
      const response = await fetch(url);
      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: Failed to fetch stock details for ${productName}`);
      }
      const data = await response.json();
      if (data.Success === 1 && data.Messages === "Product does not exist") {
        return { tableIndex, rowIndex, error: "Product does not exist" };
      }
      if (typeParam === "Counter") {
        return {
          tableIndex,
          rowIndex,
          data: {
            OpeningStock: Number(data.OpeningStock || 0),
            CounterReceived: Number(data.CounterReceived || 0),
            Sales: Number(data.Sales || 0),
            Price: Number(data.Price || 0),
          },
        };
      } else {
        return {
          tableIndex,
          rowIndex,
          data: {
            OpeningStock: Number(data.OpeningStock || 0),
            Purchase: Number(data.Purchase || 0),
            Sales: Number(data.sales || 0),
            Counter_Transfer: Number(data.Counter_Transfer || 0),
            CounterReceived: Number(data.CounterReceived || 0),
            ClosingStock: Number(data.no_btl_CBs || 0),
          },
        };
      }
    } catch (err) {
      console.error(`Error fetching stock details for ${productName}:`, err);
      showToast(`Failed to fetch stock details for ${productName}: ${err.message}`, "error");
      return { tableIndex, rowIndex, error: err.message };
    }
  };

  const handleFileChange = async (event) => {
    if (!cNo) {
      showToast("No c_no provided in URL", "error");
      return;
    }
    const file = event.target.files[0];
    if (!file) return;
    if (!isOpenCvReady) {
      showToast("OpenCV.js is not loaded yet. Please try again.", "error");
      return;
    }
    const isCameraImage = file.type.includes("image") && !file.name.includes(".pdf");
    if (isCameraImage) {
      processCameraImage(file);
    } else {
      processImage(file);
    }
  };

  const processCameraImage = async (file) => {
    setIsLoading(true);
    setError(null);
    setTablesData([]);
    setJsonOutput(null);
    setStockDetails({});
    setStockResultsState([]);
    setProgress(0);

    const progressInterval = setInterval(() => {
      setProgress((prev) => {
        const next = prev + (100 - prev) * 0.1;
        return next > 95 ? 95 : next;
      });
    }, 200);

    try {
      const imageUrl = URL.createObjectURL(file);
      const img = new Image();
      img.src = imageUrl;

      img.onload = () => {
        const canvas = document.createElement("canvas");
        canvas.width = img.width;
        canvas.height = img.height;
        const ctx = canvas.getContext("2d");
        ctx.drawImage(img, 0, 0);

        let src = window.cv.imread(canvas);
        let gray = new window.cv.Mat();
        let dst = new window.cv.Mat();
        let sharpened = new window.cv.Mat();
        // Convert to grayscale
        window.cv.cvtColor(src, gray, window.cv.COLOR_RGBA2GRAY);
        // Increase contrast and brightness
        gray.convertTo(gray, -1, 1.5, 30); // alpha=1.5 (contrast), beta=30 (brightness)
        // Adaptive threshold for scan effect
        window.cv.adaptiveThreshold(
          gray,
          dst,
          255,
          window.cv.ADAPTIVE_THRESH_GAUSSIAN_C,
          window.cv.THRESH_BINARY,
          11,
          2
        );
        // Sharpening kernel
        let kernel = window.cv.matFromArray(3, 3, window.cv.CV_32F, [
          0, -1, 0,
          -1, 5, -1,
          0, -1, 0
        ]);
        window.cv.filter2D(dst, sharpened, window.cv.CV_8U, kernel);
        window.cv.imshow(canvas, sharpened);
        src.delete();
        gray.delete();
        dst.delete();
        kernel.delete();
        sharpened.delete();

        canvas.toBlob(async (blob) => {
          const processedFile = new File([blob], file.name, {
            type: file.type,
            lastModified: file.lastModified,
          });
          const processedImageUrl = URL.createObjectURL(processedFile);
          setImage(processedImageUrl);
          await analyzeImageWithAI(processedFile);
          clearInterval(progressInterval);
          setProgress(100);
          setIsLoading(false);
        }, file.type);
      };

      img.onerror = (err) => {
        console.error("Error loading image:", err);
        setError("Failed to load image for processing");
        showToast("Failed to load image for processing", "error");
        clearInterval(progressInterval);
        setIsLoading(false);
      };
    } catch (error) {
      console.error("Error processing camera image:", error);
      setError(`Failed to process camera image: ${error.message}`);
      showToast(`Failed to process camera image: ${error.message}`, "error");
      clearInterval(progressInterval);
      setIsLoading(false);
    }
  };

  const processImage = async (file) => {
    setIsLoading(true);
    setError(null);
    setTablesData([]);
    setJsonOutput(null);
    setStockDetails({});
    setStockResultsState([]);
    setProgress(0);

    const progressInterval = setInterval(() => {
      setProgress((prev) => {
        const next = prev + (100 - prev) * 0.1;
        return next > 95 ? 95 : next;
      });
    }, 200);

    const imageUrl = URL.createObjectURL(file);
    setImage(imageUrl);
    await analyzeImageWithAI(file);
    clearInterval(progressInterval);
    setProgress(100);
    setIsLoading(false);
  };

  const analyzeImageWithAI = async (file) => {
    try {
      const base64Image = await toBase64(file);
      const apiKey = "AIzaSyC7_3o0K1LeIFgn4u9tO-_YZAIUmSc72gg";
      if (!apiKey) throw new Error("Gemini API key is missing");

      const endpoint = `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-pro-preview-05-06:generateContent?key=${apiKey}`;
      const requestBody = JSON.stringify({
        contents: [
          {
            parts: [
              { inlineData: { mimeType: file.type, data: base64Image } },
              {
                text: `Extract ONLY all tables from this image, starting from the first row that contains either a serial number or "opening balance" (whichever appears first). 
For each table, output an array of arrays (including header and total rows if present). 
Each table must have correct mapping of product name (or equivalent) with all other columns. 
Return a single JSON array of tables, where each table is an array of arrays. 
Do NOT include any extra text, explanation, markdown, or formatting—output strictly valid JSON only. 
If no tables are found, return an empty JSON array [].`,
              },
            ],
          },
        ],
      });

      const response = await fetch(endpoint, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: requestBody,
      });

      const data = await response.json();
      if (data.error) throw new Error(`Gemini API Error: ${data.error.message}`);

      const extractedText = data.candidates?.[0]?.content?.parts?.[0]?.text || "[]";
      let parsedTables = [];
      try {
        let cleanedText = extractedText
          .trim()
          .replace(/```json\n?|\n?```/g, "")
          .replace(/```/g, "")
          .replace(/,\s*([\]}])/g, "$1");
        const firstBracket = cleanedText.indexOf("[");
        const lastBracket = cleanedText.lastIndexOf("]");
        if (firstBracket === -1 || lastBracket === -1)
          throw new Error("No valid JSON array found in response");
        cleanedText = cleanedText.substring(firstBracket, lastBracket + 1);
        parsedTables = cleanedText && cleanedText !== "[]" ? JSON.parse(cleanedText) : [];

        if (!Array.isArray(parsedTables))
          throw new Error("Response is not an array of tables");

        parsedTables = parsedTables.map((table, tableIndex) => {
          if (!Array.isArray(table) || !table.every((row) => Array.isArray(row))) {
            return [["Error in table format"]];
          }
          const headers = table[0];
          const maxCols = Math.max(...table.map((row) => row.length));
          const sanitizedTable = table.map((row, rowIdx) => {
            while (row.length < maxCols) row.push("");
            return row.map((cell, i) => {
              if (rowIdx === 0) {
                return typeof cell === "string" ? cell : String(cell || "");
              }
              if (
                i > 0 &&
                headers[i]
                  .toLowerCase()
                  .match(/rate|out sale|amount|o\.b|ksbcl receipt|cou\. trsfer|cou\ntrsfer|total|c.b.|sale|receipt/) &&
                (cell === null || cell === undefined || isNaN(cell) || cell === "-" || cell === "—" || cell === "0" || cell === 0 || cell === "")
              ) {
                return 0;
              }
              if (
                i > 0 &&
                !isNaN(cell) &&
                cell !== "" &&
                headers[i]
                  .toLowerCase()
                  .match(/rate|out sale|amount|o\.b|ksbcl receipt|cou\. trsfer|cou\ntrsfer|receipt/)
              ) {
                return Number(cell);
              }
              return String(cell || "");
            });
          });

          return [
            sanitizedTable[0],
            ...sanitizedTable.slice(1).filter((row) =>
              row.slice(1).some((cell) => !(cell === 0 || cell === "0" || cell === "" || cell === null || cell === undefined || isNaN(cell)))
            ),
          ];
        });

        const tableJSON = convertTableToJSON(parsedTables);
        const stockPromises = [];
        tableJSON.tables.forEach((table, tableIndex) => {
          table.forEach((row, rowIndex) => {
            const productNameRaw =
              row["Name of Brands"] || row["name of brands"] || row.Product || row.product || row.Item || row.item;
            const productName = typeof productNameRaw === "string" ? productNameRaw.trim() : productNameRaw;
            if (productName && typeof productName === "string" && !productName.toLowerCase().includes("total")) {
              stockPromises.push(fetchProductStockDetails(productName, tableIndex, rowIndex));
            }
          });
        });

        const stockResults = await Promise.all(stockPromises);
        setStockResultsState(stockResults);

        const newStockDetails = {};
        stockResults.forEach((result) => {
          if (result && !result.error) {
            const key = `${result.tableIndex}-${result.rowIndex}`;
            newStockDetails[key] = result.data;
          }
        });
        setStockDetails(newStockDetails);

        const validationTypes = ["Validation"];
        const amountValues = [];
        const updatedTables = parsedTables.map((table, tableIndex) => {
          const headers = table[0];
          const amountIndex = headers.findIndex((h) => typeof h === "string" && h.toLowerCase() === "amount");
          const rateIndex = headers.findIndex((h) => typeof h === "string" && h.toLowerCase() === "rate");
          const outSaleIndex = headers.findIndex((h) =>
            typeof h === "string" && (h.toLowerCase() === "out sale" || h.toLowerCase() === "out\nsale" || h.toLowerCase() === "sale")
          );
          const obIndex = headers.findIndex((h) =>
            typeof h === "string" && (h.toLowerCase() === "o.b" || h.toLowerCase() === "о.b." || h.toLowerCase() === "o.b.")
          );
          const ksbclIndex = headers.findIndex((h) =>
            typeof h === "string" &&
            (h.toLowerCase() === "ksbcl\nreceipt" ||
              h.toLowerCase() === "receipt" ||
              h.toLowerCase() === "ksbcl receipt" ||
              h.toLowerCase() === "ksbol receipt" ||
              h.toLowerCase() === "ksbol\nreceipt")
          );
          const productIndex = headers.findIndex((h) =>
            typeof h === "string" && (h.toLowerCase() === "name of brands" || h.toLowerCase() === "product" || h.toLowerCase() === "item")
          );
          const counterTransferIndex = headers.findIndex((h) =>
            typeof h === "string" &&
            (h.toLowerCase() === "cou. trsfer" || h.toLowerCase() === "cou\ntrsfer" || h.toLowerCase() === "counter transfer")
          );
          const totalIndex = headers.findIndex((h) => typeof h === "string" && h.toLowerCase() === "total");
          const dataRows = table.slice(1);
          let tableTotal = 0;

          const checkedOBProducts = new Set();
          const updatedRows = dataRows.map((row, rowIndex) => {
            const isTotalRow = row[0].toLowerCase().includes("total") || row[0].toLowerCase().includes("grand total");
            const validations = [];
            const stockData = stockResults.find((r) => r.tableIndex === tableIndex && r.rowIndex === rowIndex);
            const productNameRaw = productIndex !== -1 ? row[productIndex] : "";
            const isDuplicateProduct = typeof productNameRaw === "string" && productNameRaw.match(/^\s*\d+\s*$/);

            if (!isTotalRow) {
              if (productIndex !== -1 && (!row[productIndex] || row[productIndex] === "")) {
                validations.push("Missing or empty Product Name");
              }

              if (!isDuplicateProduct && obIndex !== -1 && stockData?.data?.OpeningStock !== undefined) {
                const productName = cleanProductName(productNameRaw);
                if (!checkedOBProducts.has(productName)) {
                  const obValue = Number(row[obIndex]);
                  if (isNaN(obValue)) {
                    validations.push(`Invalid Opening Balance: "${row[obIndex]}" is not a valid number`);
                  } else if (obValue !== stockData.data.OpeningStock) {
                    validations.push(`OB Mismatch: ${obValue} does not match expected ${stockData.data.OpeningStock}`);
                  }
                  checkedOBProducts.add(productName);
                }
              } else if (!isDuplicateProduct && obIndex !== -1 && !stockData?.data) {
                validations.push("Opening Balance: No stock data available");
              }

              if (typeParam === "Counter") {
                if (!isDuplicateProduct && ksbclIndex !== -1 && stockData?.data?.CounterReceived !== undefined) {
                  const receiptValue = Number(row[ksbclIndex]);
                  if (isNaN(receiptValue)) {
                    validations.push(`Invalid Receipt: "${row[ksbclIndex]}" is not a valid number`);
                  } else if (receiptValue !== stockData.data.CounterReceived) {
                    validations.push(`Receipt Mismatch: ${receiptValue} does not match expected ${stockData.data.CounterReceived}`);
                  }
                } else if (!isDuplicateProduct && ksbclIndex !== -1 && !stockData?.data) {
                  validations.push("Receipt: No stock data available");
                }

                if (
                  !isDuplicateProduct &&
                  outSaleIndex !== -1 &&
                  stockData?.data?.Sales !== undefined &&
                  stockData.data.Sales > 0
                ) {
                  const saleValue = Number(row[outSaleIndex]);
                  if (isNaN(saleValue)) {
                    validations.push(`Invalid Sale: "${row[outSaleIndex]}" is not a valid number`);
                  } else if (saleValue !== stockData.data.Sales) {
                    validations.push(`Sale Mismatch: ${saleValue} does not match expected ${stockData.data.Sales}`);
                  }
                } else if (!isDuplicateProduct && outSaleIndex !== -1 && !stockData?.data) {
                  validations.push("Sale: No stock data available");
                }

                if (rateIndex !== -1 && totalIndex !== -1 && amountIndex !== -1 && stockData?.data) {
                  const rateValue = Number(row[rateIndex]);
                  const cbValue = Number(row[totalIndex]) - Number(row[outSaleIndex]);
                  const actualAmount = Number(row[amountIndex]);
                  const expectedAmount = stockData.data.Price * Number(row[outSaleIndex]);

                  if (isNaN(rateValue)) {
                    validations.push(`Invalid Rate: "${row[rateIndex]}" is not a valid number`);
                  } else if (rateValue !== stockData.data.Price) {
                    validations.push(`Rate Mismatch: ${rateValue} does not match expected ${stockData.data.Price}`);
                  }

                  if (isNaN(cbValue)) {
                    validations.push(`Invalid Closing Balance: "${row[totalIndex]}" is not a valid number`);
                  }

                  if (isNaN(actualAmount)) {
                    validations.push(`Invalid Amount: "${row[amountIndex]}" is not a valid number`);
                  } else if (Math.abs(actualAmount - expectedAmount) > 0.01) {
                    validations.push(`Amount Mismatch: Expected ${expectedAmount.toFixed(2)}, but got ${actualAmount}`);
                  }
                }
              } else {
                if (!isDuplicateProduct && ksbclIndex !== -1 && stockData?.data?.Purchase !== undefined) {
                  const ksbclValue = Number(row[ksbclIndex]);
                  if (isNaN(ksbclValue)) {
                    validations.push(`Invalid KSBCL Receipt: "${row[ksbclIndex]}" is not a valid number`);
                  } else if (ksbclValue !== stockData.data.Purchase) {
                    validations.push(`KSBCL Receipt Mismatch: ${ksbclValue} does not match expected ${stockData.data.Purchase}`);
                  }
                } else if (!isDuplicateProduct && ksbclIndex !== -1 && !stockData?.data) {
                  validations.push("KSBCL Receipt: No stock data available");
                }

                if (
                  !isDuplicateProduct &&
                  counterTransferIndex !== -1 &&
                  stockData?.data?.Counter_Transfer !== undefined
                ) {
                  const counterTransferValue = Number(row[counterTransferIndex]);
                  if (isNaN(counterTransferValue)) {
                    validations.push(`Invalid Counter Transfer: "${row[counterTransferIndex]}" is not a valid number`);
                  } else if (
                    counterTransferValue !== stockData.data.Counter_Transfer &&
                    stockData.data.Counter_Transfer > 0 &&
                    stockData.data.Counter_Transfer !== null
                  ) {
                    validations.push(
                      `Counter Transfer Mismatch: ${counterTransferValue} does not match expected ${stockData.data.Counter_Transfer}`
                    );
                  }
                } else if (!isDuplicateProduct && counterTransferIndex !== -1 && !stockData?.data) {
                  validations.push("Counter Transfer: No stock data available");
                }

                if (rateIndex !== -1 && outSaleIndex !== -1 && amountIndex !== -1) {
                  const rateValue = Number(row[rateIndex]);
                  const saleValue = Number(row[outSaleIndex]);
                  const actualAmount = Number(row[amountIndex]);
                  if (isNaN(actualAmount)) {
                    validations.push(`Invalid Amount: "${row[amountIndex]}" is not a valid number`);
                  } else if (!isNaN(rateValue) && !isNaN(saleValue)) {
                    const closeBalance = stockData?.data?.ClosingStock || 0;
                    let calculatedAmount = 0;
                    if (closeBalance > 0) {
                      calculatedAmount = (saleValue / closeBalance) * rateValue;
                    }
                    if (Math.abs(actualAmount - calculatedAmount) > 0.01) {
                      validations.push(
                        `Amount Mismatch: Expected ${calculatedAmount.toFixed(2)}, but got ${actualAmount}`
                      );
                    }
                  }
                }
              }

              if (rateIndex !== -1) {
                const rateValue = Number(row[rateIndex]);
                if (isNaN(rateValue)) {
                  validations.push(`Invalid Rate: "${row[rateIndex]}" is not a valid number`);
                } else if (rateValue < 0) {
                  validations.push(`Invalid Rate: ${rateValue} cannot be negative`);
                }
              }

              if (outSaleIndex !== -1) {
                const outSaleValue = Number(row[outSaleIndex]);
                if (isNaN(outSaleValue)) {
                  validations.push(`Invalid Out Sale: "${row[outSaleIndex]}" is not a valid number`);
                } else if (outSaleValue < 0) {
                  validations.push(`Invalid Out Sale: ${outSaleValue} cannot be negative`);
                }
              }

              if (stockData?.error) {
                validations.push(`Stock Data Error: ${stockData.error}`);
              }

              if (stockData?.error === "Product does not exist") {
                validations.length = 0;
                validations.push("Error: Product Name Spelling Wrong");
              }
              if (amountIndex !== -1) {
                const amount = Number(row[amountIndex]);
                if (!isNaN(amount) && amount >= 0) {
                  amountValues.push({ tableIndex, rowIndex: rowIndex + 1, amount });
                  tableTotal += amount;
                } else {
                  validations.push("Invalid Amount: Cannot include in total");
                }
              }
            }

            if (isTotalRow && amountIndex !== -1) {
              const totalAmount = Number(row[amountIndex]);
              if (isNaN(totalAmount)) {
                validations.push(`Invalid Total: "${row[amountIndex]}" is not a valid number`);
              } else if (Math.abs(totalAmount - tableTotal) > 0.01) {
                validations.push(`Total Mismatch: Expected ${tableTotal.toFixed(2)}, but got ${totalAmount}`);
              } else {
                validations.push("Total: Correct");
              }
            }

            return [...row, validations.join("; ") || "Correct"];
          });

          return [headers.concat(validationTypes), ...updatedRows];
        });

        setAmounts(amountValues);
        if (updatedTables.length === 0) {
          updatedTables.push([["No tables extracted"]]);
          showToast("No tables detected in the image", "warning");
        } else {
          showToast("Table extraction and validation completed!", "success");
        }
        setTablesData(updatedTables);

        const finalJSON = convertTableToJSON(updatedTables, stockResults, true);
        setJsonOutput(JSON.stringify(finalJSON, null, 2));
      } catch (parseError) {
        console.error("Error parsing JSON response:", parseError);
        setError("Failed to parse JSON response: " + parseError.message);
        setTablesData([]);
        showToast("Error processing image", "error");
      }
    } catch (error) {
      console.error("Error analyzing image:", error);
      setError("Failed to analyze the image: " + error.message);
      showToast("Error processing image", "error");
    }
  };

  const toBase64 = (file) =>
    new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve(reader.result.split(",")[1]);
      reader.onerror = (error) => reject(error);
    });

  const convertTableToJSON = (tables, stockResults = [], excludeValidation = false) => {
    if (!Array.isArray(tables) || tables.length === 0) return { tables: [] };
    const jsonTables = tables.map((table, tableIndex) => {
      if (!Array.isArray(table) || table.length === 0) return [];
      const headers = table[0] && Array.isArray(table[0]) && table[0].length > 0
        ? table[0].slice(0, table[0].length - (excludeValidation ? 1 : 0))
        : Array.from({ length: table[1]?.length || 1 }, (_, i) => `Column${i + 1}`);
      const rows = table.length > 1 ? table.slice(1) : [];
      const jsonRows = rows.map((row, rowIndex) => {
        const rowObject = {};
        headers.forEach((header, index) => {
          rowObject[header || `Column${index + 1}`] = row[index] || "";
        });
        if (!excludeValidation) {
          const stockData = stockResults.find((r) => r.tableIndex === tableIndex && r.rowIndex === rowIndex);
          if (stockData) {
            if (stockData.error) {
              rowObject.validationError = stockData.error;
            } else {
              rowObject.stockDetails = stockData.data;
            }
          }
          rowObject["validation"] = row[headers.length] || "";
        }
        return rowObject;
      });
      return jsonRows;
    });
    return { tables: jsonTables };
  };

