        }

        const lastRow = updatedTables[tableIndex][updatedTables[tableIndex].length - 1];
        if (
          lastRow && lastRow[0] &&
          (lastRow[0].toLowerCase().includes("total") || lastRow[0].toLowerCase().includes("grand total")) &&
          amountIdx !== -1
        ) {
          const totalAmount = Number(lastRow[amountIdx]);
          lastRow[headers.length - 1] = isNaN(totalAmount)
            ? `Total: invalid number (${lastRow[amountIdx]})`
            : Math.abs(totalAmount - tableTotal) > 0.01
            ? `Total Mismatch: ${totalAmount} != ${tableTotal}`
            : `Total: ${tableTotal}`;
        }

        setTablesData(updatedTables);
        setAmounts(updatedAmounts);
        setEditingRow(null);
        setEditValues([]);

        const tableJSON = convertTableToJSON(updatedTables, stockResultsState, true);
        setJsonOutput(JSON.stringify(tableJSON, null, 2));

        if (!allZeros) {
          showToast("Row updated successfully!", "success");
        }
      }
    } catch (error) {
      console.error("Error in handleSaveEdit:", error);
      showToast(`Failed to save edit: ${error.message}`, "error");
    }
  };

  const handleDeleteRow = async (tableIndex, rowIndex) => {
    try {
      const updatedTables = [...tablesData];
      const headers = updatedTables[tableIndex][0];
      updatedTables[tableIndex].splice(rowIndex + 1, 1);
      const updatedAmounts = amounts.filter((a) => !(a.tableIndex === tableIndex && a.rowIndex === rowIndex + 1));

      if (updatedTables[tableIndex].length > 1) {
        const lastRow = updatedTables[tableIndex][updatedTables[tableIndex].length - 1];
        if (
          lastRow[0] && (lastRow[0].toLowerCase().includes("total") || lastRow[0].toLowerCase().includes("grand total"))
        ) {
          const amountIndex = headers.findIndex((h) => h.toLowerCase() === "amount");
          const tableTotal = updatedAmounts
            .filter((a) => a.tableIndex === tableIndex)
            .reduce((sum, a) => sum + a.amount, 0);
          const totalAmount = Number(lastRow[amountIndex]);
          lastRow[headers.length - 1] = isNaN(totalAmount)
            ? `Total: invalid number (${lastRow[amountIndex]})`
            : Math.abs(totalAmount - tableTotal) > 0.01
            ? `Total Mismatch: ${totalAmount} != ${tableTotal}`
            : `Total: ${tableTotal}`;
        }
      }

      setTablesData(updatedTables);
      setAmounts(updatedAmounts);
      const tableJSON = convertTableToJSON(updatedTables, stockResultsState, true);
      setJsonOutput(JSON.stringify(tableJSON, null, 2));
      showToast("Row deleted successfully!", "success");
    } catch (err) {
      console.error("Error deleting row:", err);
      showToast(`Failed to delete row: ${err.message}`, "error");
    }
  };

  const toggleTooltip = (tableIndex, rowIndex) => {
    const key = `${tableIndex}-${rowIndex}`;
    setVisibleTooltip(visibleTooltip === key ? null : key);
  };
  const syntaxHighlight = (json) => {
    if (!json) return json;
    json = json.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
    return json.replace(
      /("(\\u[a-zA-Z0-9]{4}|\\[^u]|[^\\"])*"(\s*:)?|\b(true|false|null)\b|-?\d+(?:\.\d*)?(?:[eE][+\-]?\d+)?)/g,
      (match) => {
        let cls = "json-number";
        if (/^"/.test(match)) {
          cls = /:/.test(match) ? "json-key" : "json-string";
        } else if (/true|false/.test(match)) {
          cls = "json-boolean";
        } else if (/null/.test(match)) {
          cls = "json-null";
        }
        return `<span class="${cls}">${match}</span>`;
      }
    );
  };

  useEffect(() => {
    if (tablesData.length > 0 && tablesData[0].length > 0) {
      const tableJSON = convertTableToJSON(tablesData, stockResultsState, true);
      setJsonOutput(JSON.stringify(tableJSON, null, 2));
    }
  }, [tablesData, stockResultsState]);

  return (
      <div className="App">
        <>
          {toast.show && (
            <div className={`toast toast-${toast.type}`}>
              {toast.type === "success" && (
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  className="toast-icon"
                  width="24"
                  height="24"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                >
                  <path d="M22 11.08V12a10 10 0 11-5.93-9.14"></path>
                  <polyline points="22 4 12 14.01 9 11.01"></polyline>
                </svg>
              )}
              {toast.type === "error" && (
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  className="toast-icon"
                  width="24"
                  height="24"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                >
                  <circle cx="12" cy="12" r="10"></circle>
                  <line x1="15" y1="9" x2="9" y2="15"></line>
                  <line x1="9" y1="9" x2="15" y2="15"></line>
                </svg>
              )}
              {toast.type === "info" && (
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  className="toast-icon"
                  width="24"
                  height="24"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                >
                  <circle cx="12" cy="12" r="10"></circle>
                  <line x1="12" y1="16" x2="12" y2="12"></line>
                  <line x1="12" y1="8" x2="12.01" y2="8"></line>
                </svg>
              )}
              {toast.type === "warning" && (
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  className="toast-icon"
                  width="24"
                  height="24"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                >
                  <path d="M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z"></path>
                  <line x1="12" y1="9" x2="12" y2="13"></line>
                  <line x1="12" y1="17" x2="12.01" y2="17"></line>
                </svg>
              )}
              <span className="toast-message">{toast.message}</span>
              <button className="toast-close" onClick={closeToast}>
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  width="24"
                  height="24"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                >
                  <line x1="18" y1="6" x2="6" y2="18"></line>
                  <line x1="6" y1="6" x2="18" y2="18"></line>
                </svg>
              </button>
            </div>
          )}

          <nav className="navbar">
            <div className="navbar-container">
              <div className="navbar-items flex-row-mobile">
                {numberCounter === "2" && (
                  <select
                    value={type || ""}
                    onChange={(e) => setType(e.target.value)}
                    className="navbar-select"
                  >
                    <option value="" disabled>
                      Select Type
                    </option>
                    <option value="Counter">Counter</option>
                    <option value="Godown">Godown</option>
                  </select>
                )}
                <div className="navbar-date">
                  <input
                    type="date"
                    value={currentDate}
                    onChange={(e) => setCurrentDate(e.target.value)}
                    className="navbar-date-input"
                  />
                </div>
                <div className="navbar-upload">
                  <input
                    id="fileInput"
                    type="file"
                    accept="image/*"
                    onChange={handleFileChange}
                    className="navbar-upload-input"
                    disabled={!cNo}
                  />
                  <label htmlFor="fileInput" className="navbar-upload-label">
                    <svg
                      xmlns="http://www.w3.org/2000/svg"
                      width="24"
                      height="24"
                      viewBox="0 0 24 24"
                      fill="none"
                      stroke="currentColor"
                      strokeWidth="2"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    >
                      <path d="M3 3h18v18H3z"></path>
                      <circle cx="8.5" cy="8.5" r="1.5"></circle>
                      <polyline points="21 15 16 10 5 21"></polyline>
                    </svg>
                    Upload Image
                  </label>
                </div>
              </div>
              {isLoading && (
                <div className="progress-container">
                  <div className="progress-bar">
                    <div
                      className="progress-fill"
                      style={{ width: `${progress}%` }}
                    ></div>
                  </div>
                  <div className="progress-text">
                    Processing Image... {Math.round(progress)}%
                  </div>
                </div>
              )}
              {error && (
                <div className="error-message">
                  <svg
                    xmlns="http://www.w3.org/2000/svg"
                    width="24"
                    height="24"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  >
                    <circle cx="12" cy="12" r="10"></circle>
                    <line x1="12" y1="16" x2="12" y2="12"></line>
                    <line x1="12" y1="8" x2="12.01" y2="8"></line>
                  </svg>
                  {error}
                </div>
              )}
            </div>
          </nav>

          {image && (
            <div className="card fade-in">
              <h2 className="section-title">Image Preview</h2>
              <div className="image-preview-container">
                <img src={image} alt="Uploaded" className="image-preview" />
              </div>
            </div>
          )}

          {tablesData.length > 0 && tablesData[0].length > 0 && (
            <div className="card fade-in">
              <div className="card-header">
                <h2 className="section-title">Extracted Data Tables</h2>
              </div>
              <div className="tables-container">
                {tablesData.map((table, tableIndex) => (
                  <div key={`table-${tableIndex}`} className="table-wrapper">
                    <h3 className="table-title">Table {tableIndex + 1}</h3>
                    <div className="table-responsive">
                      <table className="data-table">
                        <thead>
                          <tr>
                            {table[0].map((header, index) => (
                              <th key={`header-${tableIndex}-${index}`}>
                                {header || `Column ${index + 1}`}
                              </th>
                            ))}
                            <th>Actions</th>
                          </tr>
                        </thead>
                        <tbody>
                          {(() => {
                            const dataRows = table
                              .slice(1)
                              .map((row, idx) => ({ row, originalIndex: idx }));

                            const correctRows = dataRows.filter(
                              (r) =>
                                r.row[table[0].length - 1] === "Correct" ||
                                r.row[table[0].length - 1] === "Total: Correct"
                            );
                            const errorRows = dataRows.filter(
                              (r) =>
                                r.row[table[0].length - 1] !== "Correct" &&
                                r.row[table[0].length - 1] !== "Total: Correct"
                            );
                            const sortedRows = [...correctRows, ...errorRows];

                            return sortedRows.map((rowObj, rowIndex) => {
                              const row = rowObj.row;
                              const originalIndex = rowObj.originalIndex;
                              const validationValue = row[table[0].length - 1];
                              const isError =
                                validationValue !== "Correct" &&
                                validationValue !== "Total: Correct";
                              const isEditing =
                                editingRow &&
                                editingRow.tableIndex === tableIndex &&
                                editingRow.rowIndex === originalIndex;

                              const productIndex = table[0].findIndex(
                                (h) =>
                                  typeof h === "string" &&
                                  (h.toLowerCase() === "name of brands" ||
                                    h.toLowerCase() === "product" ||
                                    h.toLowerCase() === "item")
                              );

                              return (
                                <tr key={`row-${tableIndex}-${rowIndex}`}>
                                  {row.map((cell, cellIndex) => (
                                    <td
                                      key={`cell-${tableIndex}-${rowIndex}-${cellIndex}`}
                                      className={
                                        cellIndex === table[0].length - 1
                                          ? "validation-cell"
                                          : ""
                                      }
                                      style={
                                        cellIndex === productIndex && isError
                                          ? { color: "#dc2626", fontWeight: 600 }
                                          : undefined
                                      }
                                    >
                                      {isEditing &&
                                      cellIndex < table[0].length - 1 ? (
                                        <input
                                          type="text"
                                          className="edit-input-small"
                                          style={
                                            cellIndex === productIndex
                                              ? {
                                                  width: `${editingRow.productInputSize}ch`,
                                                }
                                              : undefined
                                          }
                                          value={editValues[cellIndex] || ""}
                                          onChange={(e) => {
                                            const newValues = [...editValues];
                                            newValues[cellIndex] = e.target.value;
                                            setEditValues(newValues);
                                          }}
                                        />
                                      ) : cellIndex === table[0].length - 1 ? (
                                        validationValue === "Correct" ? (
                                          <span
                                            style={{
                                              color: "#16a34a",
                                              fontWeight: 600,
                                            }}
                                          >
                                            Correct
                                          </span>
                                        ) : isError ? (
                                          <OverlayTrigger
                                            placement="top"
                                            show={
                                              visibleTooltip ===
                                              `${tableIndex}-${originalIndex}`
                                            }
                                            overlay={
                                              <Tooltip>
                                                <span
                                                  style={{
                                                    userSelect: "all",
                                                    whiteSpace: "pre-line",
                                                  }}
                                                >
                                                  {validationValue ||
                                                    "No error details available"}
                                                </span>
                                              </Tooltip>
                                            }
                                          >
                                            <Button
                                              className="action-icon action-icon-view"
                                              size="sm"
                                              variant="warning"
                                              onClick={() =>
                                                toggleTooltip(
                                                  tableIndex,
                                                  originalIndex
                                                )
                                              }
                                              style={{ color: "inherit" }}
                                            >
                                              <Eye
                                                style={{ color: "currentColor" }}
                                              />
                                            </Button>
                                          </OverlayTrigger>
                                        ) : (
                                          validationValue
                                        )
                                      ) : (
                                        cell
                                      )}
                                    </td>
                                  ))}
                                  <td>
                                    {isEditing ? (
                                      <div className="flex-row-mobile">
                                        <OverlayTrigger
                                          placement="top"
                                          overlay={
                                            <Tooltip>Save Changes</Tooltip>
                                          }
                                        >
                                          <Button
                                            className="action-icon action-icon-save"
                                            size="sm"
                                            onClick={() =>
                                              handleSaveEdit(
                                                tableIndex,
                                                originalIndex
                                              )
                                            }
                                          >
                                            <Save />
                                          </Button>
                                        </OverlayTrigger>
                                        <OverlayTrigger
                                          placement="top"
                                          overlay={<Tooltip>Cancel</Tooltip>}
                                        >
                                          <button
                                            type="button"
                                            className="custom-close-btn"
                                            aria-label="Cancel"
                                            onClick={() => {
                                              setEditingRow(null);
                                              setEditValues([]);
                                            }}
                                          >
                                            ×
                                          </button>
                                        </OverlayTrigger>
                                      </div>
                                    ) : (
                                      <div className="flex-row-mobile">
                                        <OverlayTrigger
                                          placement="top"
                                          overlay={<Tooltip>Edit Row</Tooltip>}
                                        >
                                          <Button
                                            className="action-icon action-icon-edit"
                                            size="sm"
                                            onClick={() =>
                                              handleEditRow(
                                                tableIndex,
                                                originalIndex
                                              )
                                            }
                                            disabled={editingRow !== null}
                                          >
                                            <PencilSquare />
                                          </Button>
                                        </OverlayTrigger>
                                        <OverlayTrigger
                                          placement="top"
                                          overlay={<Tooltip>Delete Row</Tooltip>}
                                        >
                                          <Button
                                            className="action-icon action-icon-delete"
                                            size="sm"
                                            onClick={() =>
                                              handleDeleteRow(
                                                tableIndex,
                                                originalIndex
                                              )
                                            }
                                            disabled={editingRow !== null}
                                          >
                                            <Trash />
                                          </Button>
                                        </OverlayTrigger>
                                      </div>
                                    )}
                                  </td>
                                </tr>
                              );
                            });
                          })()}
                        </tbody>
                      </table>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          <div className="card fade-in">
            <div className="action-buttons">
              <button
                className="action-button btn-primary"
                onClick={handleSubmitSales}
                disabled={!jsonOutput || !cNo || !currentDate || isLoading}
              >
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  width="24"
                  height="24"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                >
                  <path d="M19 21H5a2 2 0 01-2-2V5a2 2 0 012-2h11l5 5v11a2 2 0 01-2 2z"></path>
                  <polyline points="17 21 17 13 7 13 7 21"></polyline>
                  <polyline points="7 3 7 8 15 8"></polyline>
                </svg>
                Final Submit
              </button>
            </div>
          </div>
        </>
        <footer style={{ textAlign: "center", marginTop: "2rem", color: "#888" }}>
          Version: {version}
        </footer>
      </div>
    );
  }


export default Camera;
